mapper.select:
select
staff_id AS staffId
from T_STAFF
where staff_type = '2' and
staff_airport_code = #{staffAirportCode}

    and staff_aptarea_code = #{staffAptareaCode}

select vehi_plate_no as vehiNo
from T_VEHI
where vehi_no = #{sfvhVehiNo}

select staff_id AS staffId, staff_name AS staffName from T_STAFF where staff_type in ('2','3','4','5')
and staff_airport_code = #{staffAirportCode}
and staff_aptarea_code = #{staffAptareaCode}

SELECT staff_group_id AS staffGroupId from T_STAFF where
staff_airport_code = #{staffAirportCode}

    and staff_aptarea_code = #{staffAptareaCode}

and staff_type=3
GROUP BY staff_group_id

mapper.update:
UPDATE T_STAFF SET staff_group_id=#{staffGroupId}
where staff_id=#{sfvhStaffId}

    AND staff_airport_code=#{staffAirportCode}


    AND staff_aptarea_code=#{staffAptareaCode}

UPDATE T_STAFF SET
staff_group_id=#{staffGroupId},
staff_level=#{staffLevel,jdbcType=INTEGER}
where staff_id=#{sfvhStaffId}

    AND staff_airport_code=#{staffAirportCode}


    AND staff_aptarea_code=#{staffAptareaCode}

UPDATE T_STAFF_VEHI
set sfvh_vehi_no = #{sfvhVehiNo}
where sfvh_staff_id = #{sfvhStaffId}

mapper.select:
select max(staff_level)
from T_STAFF
where staff_group_id = #{staffGroupId}
